@import "@fontsource-variable/fraunces";

:root {
  --background: oklch(0.975 0.012 75);
  --foreground: oklch(0.24 0.03 40);
  --card: oklch(0.99 0.008 75);
  --card-foreground: oklch(0.24 0.03 40);
  --popover: oklch(0.99 0.008 75);
  --popover-foreground: oklch(0.24 0.03 40);
  --primary: oklch(0.56 0.15 38);
  --primary-foreground: oklch(0.98 0.01 75);
  --secondary: oklch(0.93 0.025 70);
  --secondary-foreground: oklch(0.3 0.04 40);
  --muted: oklch(0.94 0.018 72);
  --muted-foreground: oklch(0.5 0.03 45);
  --accent: oklch(0.92 0.035 65);
  --accent-foreground: oklch(0.3 0.04 40);
  --destructive: oklch(0.55 0.2 27);
  --destructive-foreground: oklch(0.98 0.01 75);
  --border: oklch(0.88 0.025 65);
  --input: oklch(0.86 0.03 65);
  --ring: oklch(0.56 0.15 38);
  --highlight: oklch(0.6 0.12 150);
  --highlight-foreground: oklch(0.98 0.01 75);
  --glow: oklch(0.75 0.14 55);
  --chart-1: oklch(0.56 0.15 38);
  --chart-2: oklch(0.6 0.12 150);
  --chart-3: oklch(0.7 0.13 80);
  --chart-4: oklch(0.45 0.08 250);
  --chart-5: oklch(0.65 0.1 10);
  --sidebar: oklch(0.96 0.015 72);
  --sidebar-foreground: oklch(0.24 0.03 40);
  --sidebar-primary: oklch(0.56 0.15 38);
  --sidebar-primary-foreground: oklch(0.98 0.01 75);
  --sidebar-accent: oklch(0.92 0.035 65);
  --sidebar-accent-foreground: oklch(0.3 0.04 40);
  --sidebar-border: oklch(0.88 0.025 65);
  --sidebar-ring: oklch(0.56 0.15 38);

  --typeface-body: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --typeface-display: "Fraunces Variable", Georgia, serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1rem;
  --page-width: 70rem;
  --page-gutter: 1.25rem;
  --section-y: 5rem;
}

.dark {
  --background: oklch(0.2 0.02 40);
  --foreground: oklch(0.95 0.015 75);
  --card: oklch(0.25 0.025 40);
  --card-foreground: oklch(0.95 0.015 75);
  --popover: oklch(0.25 0.025 40);
  --popover-foreground: oklch(0.95 0.015 75);
  --primary: oklch(0.68 0.15 42);
  --primary-foreground: oklch(0.18 0.02 40);
  --secondary: oklch(0.3 0.03 40);
  --secondary-foreground: oklch(0.95 0.015 75);
  --muted: oklch(0.29 0.025 40);
  --muted-foreground: oklch(0.72 0.03 60);
  --accent: oklch(0.32 0.035 40);
  --accent-foreground: oklch(0.95 0.015 75);
  --destructive: oklch(0.65 0.2 25);
  --destructive-foreground: oklch(0.98 0.01 75);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 16%);
  --ring: oklch(0.68 0.15 42);
  --highlight: oklch(0.72 0.12 150);
  --highlight-foreground: oklch(0.18 0.02 40);
  --glow: oklch(0.65 0.16 45);
  --chart-1: oklch(0.68 0.15 42);
  --chart-2: oklch(0.72 0.12 150);
  --chart-3: oklch(0.78 0.13 80);
  --chart-4: oklch(0.6 0.1 250);
  --chart-5: oklch(0.7 0.12 10);
  --sidebar: oklch(0.23 0.022 40);
  --sidebar-foreground: oklch(0.95 0.015 75);
  --sidebar-primary: oklch(0.68 0.15 42);
  --sidebar-primary-foreground: oklch(0.18 0.02 40);
  --sidebar-accent: oklch(0.32 0.035 40);
  --sidebar-accent-foreground: oklch(0.95 0.015 75);
  --sidebar-border: oklch(1 0 0 / 12%);
  --sidebar-ring: oklch(0.68 0.15 42);
}
